return array_reduce(
	array_keys( $attributes ),
	function ( $attrs, $attr_key ) use ( $prefix ) {
		return array_merge(
			$attrs,
			array(
				str_replace( $prefix, '', $attr_key ) => wc_clean( Helper::get_posted_value( $attr_key ) ),
			)
		);
	},
	array()
);

